import { useForm } from "react-hook-form";
import { useState, useEffect } from "react";
import { button as MotionButton } from "motion/react-client";
import { useTranslation } from "react-i18next";
import SmartNavLink from "./SmartNavLink";

const ContactForm = () => {
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm();
  const [leadSource, setLeadSource] = useState("website");
  const [isSent, setIsSent] = useState(false);

  useEffect(() => {
    if (typeof window !== "undefined" && window.ShipXGeo) {
      console.log("User country:", window.ShipXGeo.country);
    }
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;

    const url = new URL(window.location.href);
    const params = url.searchParams;

    const utmSource = params.get("utm_source");
    const utmMedium = params.get("utm_medium");

    if (utmSource && utmMedium) {
      const sourceKey = `${utmSource}_${utmMedium}`.toLowerCase();
      setLeadSource(sourceKey);
      return;
    }

    // Fallback to referrer
    const ref = document.referrer || "";

    if (ref.includes("facebook.com")) {
      setLeadSource("facebook_organic");
    } else if (ref.includes("google.com")) {
      setLeadSource("google_organic");
    } else if (ref.trim() !== "") {
      setLeadSource("generic_referral");
    } else {
      setLeadSource("website");
    }
  }, []);

  const onSubmit = async (data) => {
    try {
      // POST to WordPress
      const wpRes = await fetch("/wp-json/mytheme/v1/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });

      // Prepare CRM payload
      const crmPayload = {
        contactName: data.name,
        email: data.email,
        phoneNumber: data.phone || "N/A",
        leadSource,
        services: ["crossborder_shipping"], // adjust as needed
        companyId: "8d612638-ffef-4457-a876-05e655dcc93e",
        website: "https://shipx.asia/",
        description: data.message,
        location: window.ShipXGeo.country || "Unknown",
      };

      // POST to CRM API
      const crmRes = await fetch("https://crm.infigroup.co/api/public/leads", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(crmPayload),
      });

      if (!crmRes.ok) {
        throw new Error("Failed to submit to CRM");
      }

      setIsSent(true);
      setTimeout(() => setIsSent(false), 5000);
      reset();
    } catch (err) {
      console.error(err);
      alert("Something went wrong.");
    }
  };

  const { t } = useTranslation();

  return (
    <form
      onSubmit={handleSubmit(onSubmit)}
      className="flex flex-col gap-y-[1.5vw] md:text-[0.8vw] text-[2.5vw] font-normal z-10 select-none md:w-auto w-full"
      style={{ fontFamily: "Inter, system-ui, -apple-system, sans-serif" }}
    >
      <div className="flex md:flex-row flex-col gap-x-[1vw] md:gap-y-0 gap-y-[5vw]">
        <div className="flex flex-col">
          <label className="text-nowrap" htmlFor="name">
            {t("contact_us_section.form.name")}
          </label>
          <input
            aria-invalid={errors.name ? "true" : "false"}
            id="name"
            className={`border-b border-[#CACACA] w-full p-2 focus:outline-none ${errors.name ? "placeholder-red-500" : "placeholder-black/50"}`}
            {...register("name", {
              required: t("contact_us_section.form.name_placeholder"),
            })}
            placeholder={errors.name ? errors.name.message : ""}
            autoComplete="name"
          />
        </div>
        <div className="flex flex-col">
          <label className="text-nowrap" htmlFor="email">
            {t("contact_us_section.form.email")}
          </label>
          <input
            aria-invalid={errors.email ? "true" : "false"}
            id="email"
            type="email"
            className={`border-b border-[#CACACA] w-full p-2 focus:outline-none ${errors.email ? "placeholder-red-500" : "placeholder-black/50"}`}
            {...register("email", {
              required: t("contact_us_section.form.email_placeholder_1"),
              pattern: {
                value: /^\S+@\S+$/i,
                message: t("contact_us_section.form.email_placeholder_2"),
              },
            })}
            placeholder={errors.email ? errors.email.message : ""}
            autoComplete="email"
          />
        </div>
        <div className="flex flex-col">
          <label className="text-nowrap" htmlFor="tel">
            {t("contact_us_section.form.phone")}
          </label>
          <input
            aria-invalid={errors.phone ? "true" : "false"}
            id="tel"
            type="tel"
            className={`border-b border-[#CACACA] w-full p-2 focus:outline-none ${errors.name ? "placeholder-red-500" : "placeholder-black/50"}`}
            {...register("phone", {
              pattern: {
                value: /^\+?[\d\s\-()]{7,}$/,
                message: t("contact_us_section.form.phone_placeholder"),
              },
            })}
            inputMode="tel"
            autoComplete="tel"
            placeholder={errors.phone ? errors.phone.message : ""}
          />
        </div>
      </div>

      <div className="flex flex-col md:mt-[1vw] mt-0 md:pt-0 pt-[5vw]">
        <label className="text-nowrap" htmlFor="message">
          {t("contact_us_section.form.message")}
        </label>
        <textarea
          aria-invalid={errors.message ? "true" : "false"}
          id="message"
          className={`border-b border-[#CACACA] w-full resize-none md:h-[5vw] h-[15vw] focus:outline-none ${errors.name ? "placeholder-red-500" : "placeholder-black/50"}`}
          {...register("message", {
            required: t("contact_us_section.form.message_placeholder"),
          })}
          placeholder={errors.message ? errors.message.message : ""}
          autoComplete="off"
        />
      </div>

      <div className="flex flex-row md:gap-x-[1vw] gap-x-[3vw] md:text-[0.8vw] text-[2.5vw] font-normal justify-start items-center md:mt-[1vw] mt-0 md:pt-0 pt-[5vw]">
        <button
          type="submit"
          disabled={isSubmitting}
          className="
            bg-linear-to-r from-[#4F378A] from-0% via-[#FF00E5] via-60% to-[#FF00E5] to-100%
            bg-size-[200%_100%] bg-position-[0%_0%]
            hover:bg-position-[100%_0%]
            transition-[background-position] duration-1000 ease-in-out
            md:py-[0.6vw] py-[1vw] md:px-[1.5vw] px-[3vw] md:rounded-[2vw] rounded-full cursor-pointer
            text-white font-medium shadow-[0_0.5vw_1vw_rgba(255,0,229,0.25)]
          "
        >
          {isSubmitting
            ? t("contact_us_section.form.button_sending")
            : isSent
              ? t("contact_us_section.form.button_sent")
              : t("contact_us_section.form.button_default")}
        </button>

        <SmartNavLink
          to="/book-a-demo"
          className="text-[#4F378A] font-semibold"
        >
          <MotionButton
            type="button"
            className="md:p-[0.15vw] p-[0.5vw] rounded-full relative overflow-hidden cursor-pointer"
            whileHover={{
              y: -5,
              transition: { type: "spring", stiffness: 300, damping: 15 },
            }}
            whileTap={{
              scale: 0.9,
              transition: { type: "spring", stiffness: 500, damping: 10 },
            }}
          >
            {/* Gradient border */}
            <div className="absolute inset-0 bg-linear-to-r from-[#4F378A] to-[#FF00E5] rounded-full" />

            {/* Inner white area */}
            <div className="relative flex flex-row items-center gap-x-[1vw] md:px-[2vw] px-[5vw] md:py-[0.5vw] py-[1vw] bg-white rounded-full">
              {t("contact_us_section.form.book_a_demo")}
            </div>
          </MotionButton>
        </SmartNavLink>
      </div>
    </form>
  );
};

export default ContactForm;
